<?php
require_once __DIR__.'/includes/functions.php';$token=$_POST['token']??$_GET['token']??'';$valid=is_string($token)&&preg_match('/^[a-f0-9]{64}$/',$token);$reset=null;if($valid){$s=db()->prepare('SELECT id,account_id FROM customer_password_resets WHERE token_hash=? AND expires_at>NOW() AND used_at IS NULL');$s->execute([hash('sha256',$token)]);$reset=$s->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pw=$_POST['password']??'';if(!$reset||strlen($pw)<10||$pw!==($_POST['confirm_password']??'')){flash('error','Reset link is invalid or expired, or the passwords do not match.');}else{$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE customer_accounts SET password_hash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$reset['account_id']]);$pdo->prepare('UPDATE customer_password_resets SET used_at=NOW() WHERE id=?')->execute([$reset['id']]);$pdo->commit();flash('success','Password changed. You can sign in now.');header('Location: account.php');exit;}}$page_title='Choose a new password';require 'includes/header.php';?><section class="section"><div class="container auth-card"><p class="eyebrow">Account recovery</p><h1>Choose a new password</h1><?php if(!$reset):?><p>This reset link is invalid or has expired.</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="token" value="<?=e($token)?>"><label>New password<input required type="password" name="password" minlength="10"></label><label>Confirm password<input required type="password" name="confirm_password" minlength="10"></label><button class="button primary">Update password</button></form><?php endif?></div></section><?php require 'includes/footer.php';
